INSERT INTO skills (name, icon, type, description) VALUES
    ('Acrobatics', (SELECT id FROM icons WHERE name = 'jump-across' LIMIT 1), 'Core', $desc$Mastery of body movement and agility.$desc$),
    ('Awareness', (SELECT id FROM icons WHERE name = 'awareness' LIMIT 1), 'Core', $desc$Heightened perception and vigilance.$desc$),
    ('Bartering', (SELECT id FROM icons WHERE name = 'scales' LIMIT 1), 'Core', $desc$The art of negotiation and vigilance.$desc$),
    ('Beast Lore', (SELECT id FROM icons WHERE name = 'paw' LIMIT 1), 'Core', $desc$Skill in understanding and interacting with creatures.$desc$),
    ('Bluffing', (SELECT id FROM icons WHERE name = 'double-face-mask' LIMIT 1), 'Core', $desc$Deceptive communication and misdirection.$desc$),
    ('Bushcraft', (SELECT id FROM icons WHERE name = 'campfire' LIMIT 1), 'Core', $desc$Wilderness survival skills.$desc$),
    ('Crafting', (SELECT id FROM icons WHERE name = 'crafting' LIMIT 1), 'Core', $desc$The ability to repair, create, and modify items.$desc$),
    ('Evade', (SELECT id FROM icons WHERE name = 'dodging' LIMIT 1), 'Core', $desc$Quick reflexes and dodging capabilities.$desc$),
    ('Healing', (SELECT id FROM icons WHERE name = 'healing' LIMIT 1), 'Core', $desc$Knowledge of medicinal arts and first aid.$desc$),
    ('Hunting and Fishing', (SELECT id FROM icons WHERE name = 'fishing' LIMIT 1), 'Core', $desc$Expertise in procuring sustenance from the wild.$desc$),
    ('Languages', (SELECT id FROM icons WHERE name = 'chat-bubble' LIMIT 1), 'Core', $desc$Proficiency in additional languages.$desc$),
    ('Myths and Legends', (SELECT id FROM icons WHERE name = 'book-cover' LIMIT 1), 'Core', $desc$Knowledge of folklore, mythology, and historycal legends.$desc$),
    ('Performance', (SELECT id FROM icons WHERE name = 'sing' LIMIT 1), 'Core', $desc$Skill in entertaining and captivating an audience.$desc$),
    ('Persuasion', (SELECT id FROM icons WHERE name = 'convince' LIMIT 1), 'Core', $desc$The ability to influence and sway others.$desc$),
    ('Riding', (SELECT id FROM icons WHERE name = 'cavalry' LIMIT 1), 'Core', $desc$Proficiency in mounted travel.$desc$),
    ('Seamanship', (SELECT id FROM icons WHERE name = 'sailboat' LIMIT 1), 'Core', $desc$Proficiency in the maritime arts.$desc$),
    ('Sleight of Hand', (SELECT id FROM icons WHERE name = 'coinflip' LIMIT 1), 'Core', $desc$Dexterity and finesse in manual trickery.$desc$),
    ('Sneaking', (SELECT id FROM icons WHERE name = 'sprint' LIMIT 1), 'Core', $desc$Stealth and subtlety in movement.$desc$),
    ('Spot Hidden', (SELECT id FROM icons WHERE name = 'magnifying-glass' LIMIT 1), 'Core', $desc$The ability to notice concealed details and hidden objects.$desc$),
    ('Swimming', (SELECT id FROM icons WHERE name = 'pool-dive' LIMIT 1), 'Core', $desc$Proficiency in aquatic movement.$desc$),
    ('Axes', (SELECT id FROM icons WHERE name = 'crossed-axes' LIMIT 1), 'Core', $desc$Axes of all kinds, also when thrown.$desc$),
    ('Bows', (SELECT id FROM icons WHERE name = 'bow-arrow' LIMIT 1), 'Core', $desc$All types of bows, except crossbows.$desc$),
    ('Brawling', (SELECT id FROM icons WHERE name = 'high-punch' LIMIT 1), 'Core', $desc$Unarmed combat with fists, feet, teeth, or claws.$desc$),
    ('Crossbows', (SELECT id FROM icons WHERE name = 'crossbow' LIMIT 1), 'Core', $desc$Crossbows of all kinds.$desc$),
    ('Hammers', (SELECT id FROM icons WHERE name = 'gavel' LIMIT 1), 'Core', $desc$Blunt weapons, warhammers, clubs, flails and maces.$desc$),
    ('Knives', (SELECT id FROM icons WHERE name = 'kitchen-knives' LIMIT 1), 'Core', $desc$Knives and daggers, including when thrown.$desc$),
    ('Slings', (SELECT id FROM icons WHERE name = 'sling' LIMIT 1), 'Core', $desc$Attacking with a sling.$desc$),
    ('Spears', (SELECT id FROM icons WHERE name = 'spears' LIMIT 1), 'Core', $desc$Spears, lances, halberds and tridents, also when thrown.$desc$),
    ('Staves', (SELECT id FROM icons WHERE name = 'wizard-staff' LIMIT 1), 'Core', $desc$Fighting with a staff.$desc$),
    ('Swords', (SELECT id FROM icons WHERE name = 'crossed-swords' LIMIT 1), 'Core', $desc$All types of swords.$desc$),
    ('Adaptive', (SELECT id FROM icons WHERE name = 'chameleon-glyph' LIMIT 1), 'Innate', $desc$When rolling for a skill, you can choose to make the roll using another skill of your choice. You must be able to justify how you use the selected skill instead of the normal one. The GM has the final word, but should be lenient.$desc$),
    ('Hard To Catch', (SELECT id FROM icons WHERE name = 'swirl-ring' LIMIT 1), 'Innate', $desc$You can activate this ability when dodging an attack, getting a boon to the EVADE roll.$desc$),
    ('Unforgiving', (SELECT id FROM icons WHERE name = 'enrage' LIMIT 1), 'Innate', $desc$You can activate this ability when attacking someone who harmed you in the past (at least 1 point of damage) and get a boon to the roll. It does not matter when the damage was inflicted. It may be wise to write down the names of everyone who harms you, so you do not forget them.$desc$),
    ('Inner Peace', (SELECT id FROM icons WHERE name = 'meditation' LIMIT 1), 'Innate', $desc$As an elf, you can meditate deeply during a stretch rest. You heal an additional D6 HP and a D6 extra WP, and can recover from an additional condition. You are completely unresponsive during your meditation and cannot be awakened.$desc$),
    ('Ill Tempered', (SELECT id FROM icons WHERE name = 'angry-eyes' LIMIT 1), 'Innate', $desc$Mallards tend to have a choleric temper. You can activate this ability (no action) when making a skill roll and get a boon to the roll. You also become Angry, if you're not already. This ability cannot be used for rolls against INT or IN-based skills.$desc$),
    ('Webbed Feet', (SELECT id FROM icons WHERE name = 'duck-palm' LIMIT 1), 'Innate', $desc$As a mallard you also get a boon to all SWIMMING rolls. You always move at full speed in or under water.$desc$),
    ('Hunting Instinct', (SELECT id FROM icons WHERE name = 'beast-eye' LIMIT 1), 'Innate', $desc$You can use this ability to designate a creature in sight, or a creature you can catch the scent of, as your prey. This counts as an action in combat. You can follow the scent of your prey for a full day, and you can spend 1 further WP (not an action) to gain a boon for an attack against your prey.$desc$),
    ('Resilient', (SELECT id FROM icons WHERE name = 'diamond-hard' LIMIT 1), 'Innate', $desc$Goblins are resilient creatures capable of withstanding all kinds of hardships. By activating this ability, goblins get a boon on a CON roll for resisting poison or disease (pages 52–53 in the rulebook) or can make camp without rolling BUSHCRAFT (page 103 in the rulebook). In addition, goblins can always eat raw food without falling ill (no WP required).$desc$),
    ('Body Slam', (SELECT id FROM icons WHERE name = 'punch-blast' LIMIT 1), 'Innate', $desc$Ogres can use their large bodies to slam an opponent with tremendous force. This counts as an unarmed melee attack with a boon that inflicts 2D6 bludgeoning damage (excluding the damage bonus) and cannot be parried. The ogre can also dash before the attack (but does not have to). Humanoid targets of Normal size or smaller who are hit by the attack are automatically knocked down.$desc$),
    ('Tough', (SELECT id FROM icons WHERE name = 'rock' LIMIT 1), 'Innate', $desc$Orcs can take extraordinary amounts of pain and keep on fighting. An orc with zero HP can activate this ability to automatically rally (page 50 in the rulebook), without rolling against WIL or being PERSUADED by someone else. Usually, this ability is only used by player characters and important NPCs.$desc$),
    ('Nine Lives', (SELECT id FROM icons WHERE name = 'cat' LIMIT 1), 'Innate', $desc$Cat people have an incredible ability to emerge unscathed from even the worst of ordeals. Activating this ability grants a boon on a death roll (page 50 in the rulebook), at the cost of 3 WP. The ability can also be used to reduce the number of D6s rolled for fall damage by one per WP up to a maximum of three (after the ACROBATICS roll to mitigate the damage, see page 53 in the rulebook).$desc$),
    ('Leaping', (SELECT id FROM icons WHERE name = 'leapfrog' LIMIT 1), 'Innate', $desc$Frog people can activate this ability to jump as far as their movement rating horizontally, or up to half their movement rating vertically. No ACROBATICS roll is required. The jump can end with a melee attack, which is made with a boon.$desc$),
    ('Wings', (SELECT id FROM icons WHERE name = 'spiky-wing' LIMIT 1), 'Innate', $desc$The bat-like wings of a karkion allow it to move freely through the air at the same speed as on foot, at the cost of 1 WP per round.$desc$),
    ('Camouflage', (SELECT id FROM icons WHERE name = 'hidden' LIMIT 1), 'Innate', $desc$Lizard people who wish to stay hidden are hard to spot. Activating this ability grants a boon on a SNEAKING roll.$desc$),
    ('Raise Spirits', (SELECT id FROM icons WHERE name = 'morbid-humour' LIMIT 1), 'Innate', $desc$Satyrs are cheerful and optimistic creatures who like to raise their friends' spirits with song or poetry. Activating this ability counts as an action and removes a chosen condition from a person within earshot and 10 meters. The ability cannot be used on the satyr itself.$desc$),
    ('Assassin', (SELECT id FROM icons WHERE name = 'hooded-assassin' LIMIT 1), 'Heroic', $desc$Your sneak attack deals an extra D8 damage.$desc$),
    ('Backstabbing', (SELECT id FROM icons WHERE name = 'backstab' LIMIT 1), 'Heroic', $desc$Melee attack against an enemy close to another player. Your sneak attack cannot be dodged or parried, have a boon and the number of dice rolled for the damage is increased by one.$desc$),
    ('Battle Cry', (SELECT id FROM icons WHERE name = 'shouting' LIMIT 1), 'Heroic', $desc$All other player characters in combat within earshot immediately heal a condition of their choice.$desc$),
    ('Berserker', (SELECT id FROM icons WHERE name = 'mighty-force' LIMIT 1), 'Heroic', $desc$You gain the Angry condition and a boon to melee attacks, but can not parry or dodge. After the fight you become Exhausted.$desc$),
    ('Catlike', (SELECT id FROM icons WHERE name = 'cat' LIMIT 1), 'Heroic', $desc$The number of D6 rolled for damage from a fall decreases by one for each WP spent.$desc$),
    ('Companion', (SELECT id FROM icons WHERE name = 'feline' LIMIT 1), 'Heroic', $desc$Turn one animal (not a monster) into your companion. The animal can scout and also attack for a WP cost of 3.$desc$),
    ('Contortionist', (SELECT id FROM icons WHERE name = 'contortionist' LIMIT 1), 'Heroic', $desc$You escape from your shackles or squeeze through a narrow space without rolling for any skill.$desc$),
    ('Defensive', (SELECT id FROM icons WHERE name = 'defensive-wall' LIMIT 1), 'Heroic', $desc$Try to Parry an attack without using your action for the round.$desc$),
    ('Deflect Arrow', (SELECT id FROM icons WHERE name = 'shield-reflect' LIMIT 1), 'Heroic', $desc$You can try to Parry any ranged attack with a melee weapon.$desc$),
    ('Disguise', (SELECT id FROM icons WHERE name = 'prank-glasses' LIMIT 1), 'Heroic', $desc$You can assume another person's looks, voice, and demeanor.$desc$),
    ('Double Slash', (SELECT id FROM icons WHERE name = 'crossed-slashes' LIMIT 1), 'Heroic', $desc$Attack two enemies within 2 meters with a single slash.$desc$),
    ('Dragon Slayer', (SELECT id FROM icons WHERE name = 'dragon-head' LIMIT 1), 'Heroic', $desc$Attack aimed at a monster deals an additional D8 damage.$desc$),
    ('Dual Wield', (SELECT id FROM icons WHERE name = 'rogue' LIMIT 1), 'Heroic', $desc$Perform an extra attack with your second weapon. The second attack is done with a bane.$desc$),
    ('Eagle Eye', (SELECT id FROM icons WHERE name = 'eagle-head' LIMIT 1), 'Heroic', $desc$See persons or objects up to 200 meters away for a stretch. Shoot at a target beyond the weapon's effective range without bane.$desc$),
    ('Fast Footwork', (SELECT id FROM icons WHERE name = 'foot-trip' LIMIT 1), 'Heroic', $desc$Try to Dodge an attack without using your action for the round.$desc$),
    ('Fast Healer', (SELECT id FROM icons WHERE name = 'health-increase' LIMIT 1), 'Heroic', $desc$You heal an extra D6 HP during a stretch rest.$desc$),
    ('Fearless', (SELECT id FROM icons WHERE name = 'lion' LIMIT 1), 'Heroic', $desc$You automatically resist fear, without a WIL roll.$desc$),
    ('Focused', (SELECT id FROM icons WHERE name = 'rear-aura' LIMIT 1), 'Heroic', $desc$Max number of WP is permanently increased by 2.$desc$),
    ('Guardian', (SELECT id FROM icons WHERE name = 'guarded-tower' LIMIT 1), 'Heroic', $desc$Force the enemy to attack you instead of a close player.$desc$),
    ('Insight', (SELECT id FROM icons WHERE name = 'inspiration' LIMIT 1), 'Heroic', $desc$Roll AWARENESS to determine whether that person is telling the truth. You cannot tell exactly what a person is lying about.$desc$),
    ('Intuition', (SELECT id FROM icons WHERE name = 'idea' LIMIT 1), 'Heroic', $desc$Ask a question directly to the GM and receive a helpful answer.$desc$),
    ('Iron Fist', (SELECT id FROM icons WHERE name = 'fist' LIMIT 1), 'Heroic', $desc$The damage of an unarmed attack increases to 2D6.$desc$),
    ('Iron Grip', (SELECT id FROM icons WHERE name = 'grab' LIMIT 1), 'Heroic', $desc$You get a boon to your BRAWLING roll when grappling.$desc$),
    ('Lightning Fast', (SELECT id FROM icons WHERE name = 'running-ninja' LIMIT 1), 'Heroic', $desc$You may draw two initiative cards instead of one and choose which one you want.$desc$),
    ('Lone Wolf', (SELECT id FROM icons WHERE name = 'wolf-howl' LIMIT 1), 'Heroic', $desc$Take a shift rest without a roll for BUSHCRAFT.$desc$),
    ('Magic Talent', (SELECT id FROM icons WHERE name = 'embrassed-energy' LIMIT 1), 'Heroic', $desc$You can learn a new school of magic.$desc$),
    ('Massive Blow', (SELECT id FROM icons WHERE name = 'corner-explosion' LIMIT 1), 'Heroic', $desc$A strike with a two-handed melee weapon inflicts D* additional points of damage, but you cannot move in the same round.$desc$),
    ('Master Blacksmith', (SELECT id FROM icons WHERE name = 'blacksmith' LIMIT 1), 'Heroic', $desc$Sharpen weapons and craft metal weapons and armor.$desc$),
    ('Master Carpenter', (SELECT id FROM icons WHERE name = 'hand-saw' LIMIT 1), 'Heroic', $desc$Do D12 damage to objects and craft wood weapons and tools.$desc$),
    ('Master Chef', (SELECT id FROM icons WHERE name = 'chef-toque' LIMIT 1), 'Heroic', $desc$You automatically succeed at cooking without BUSHCRAFT.$desc$),
    ('Master SpellCaster', (SELECT id FROM icons WHERE name = 'pointy-hat' LIMIT 1), 'Heroic', $desc$You can cast two different spells in a single action. It must be two different spells.$desc$),
    ('Master Tanner', (SELECT id FROM icons WHERE name = 'animal-hide' LIMIT 1), 'Heroic', $desc$Craft leather armor from animals and monsters.$desc$),
    ('Master Hunter', (SELECT id FROM icons WHERE name = 'hunting-horn' LIMIT 1), 'Heroic', $desc$At a crossroads of some kind, you can activate this ability to learn the direction of the most dangerous enemies.$desc$),
    ('Musician', (SELECT id FROM icons WHERE name = 'musical-notes' LIMIT 1), 'Heroic', $desc$Give all allies within 10 meters a boon to all rolls, or a bane to all enemies within the same range. Lasts one turn.$desc$),
    ('Pathfinder', (SELECT id FROM icons WHERE name = 'trail' LIMIT 1), 'Heroic', $desc$You get a boon to your BUSHCRAFT roll when trying to find the right direction in the wilderness.$desc$),
    ('Quartermaster', (SELECT id FROM icons WHERE name = 'barracks-tent' LIMIT 1), 'Heroic', $desc$You automatically succeed at making camp during journeys.$desc$),
    ('Robust', (SELECT id FROM icons WHERE name = 'muscle-fat' LIMIT 1), 'Heroic', $desc$Your max HP increases by 2.$desc$),
    ('Sea Legs', (SELECT id FROM icons WHERE name = 'wave-surfer' LIMIT 1), 'Heroic', $desc$You are safe from all negative effects of being in water for one round, including the risk of drowning.$desc$),
    ('Shield Block', (SELECT id FROM icons WHERE name = 'roman-shield' LIMIT 1), 'Heroic', $desc$Parrying with a shield rolls with a boon. You can also parry physical monster attacks (not area effects) that normally cannot be parried.$desc$),
    ('Throwing Arm', (SELECT id FROM icons WHERE name = 'throwing-ball' LIMIT 1), 'Heroic', $desc$Throw a melee weapon at an enemy within your STR meters. It must be a onehanded weapon.$desc$),
    ('Treasure Hunter', (SELECT id FROM icons WHERE name = 'treasure-map' LIMIT 1), 'Heroic', $desc$At a crossroads of some kind, you can activate this ability to learn the direction of the greatest treasure.$desc$),
    ('Twin Shot', (SELECT id FROM icons WHERE name = 'double-shot' LIMIT 1), 'Heroic', $desc$When attacking with a bow (not crossbow), you shoot two arrows instead of one. Roll just once to hit, with a bane.$desc$),
    ('Veteran', (SELECT id FROM icons WHERE name = 'wisdom' LIMIT 1), 'Heroic', $desc$You may retain your initiative card from the previous round.$desc$),
    ('Weasel', (SELECT id FROM icons WHERE name = 'two-shadows' LIMIT 1), 'Heroic', $desc$If attacked and another player is within 2 meters, you can let the attack hit that player instead of you.$desc$);
